CREATE TABLE IF NOT EXISTS durable_bindings          (external_id TEXT PRIMARY KEY, session_id TEXT NOT NULL UNIQUE);          CREATE TABLE IF NOT EXISTS durable_recovery_scans          (session_id TEXT PRIMARY KEY, payload TEXT NOT NULL);          CREATE TABLE IF NOT EXISTS durable_fork_lineage          (child_id TEXT PRIMARY KEY, parent_id TEXT NOT NULL, parent_branch TEXT NOT NULL, source_end INTEGER NOT NULL);          CREATE TABLE IF NOT EXISTS durable_fork_intents          (child_id TEXT PRIMARY KEY, parent_id TEXT NOT NULL, external_id TEXT NOT NULL, version INTEGER NOT NULL);          CREATE TRIGGER IF NOT EXISTS durable_binding_lineage_cleanup AFTER DELETE ON durable_bindings          BEGIN DELETE FROM durable_fork_lineage WHERE child_id=OLD.session_id; END;          CREATE TRIGGER IF NOT EXISTS durable_binding_scan_cleanup AFTER DELETE ON durable_bindings          BEGIN DELETE FROM durable_recovery_scans WHERE session_id=OLD.session_id; END;
